        Self.captured=request
        Self.body=request.httpBody ?? Data()
        if let stream=request.httpBodyStream {
            stream.open();defer {stream.close()}
            var bytes=[UInt8](repeating:0,count:4096)
            while true {let count=stream.read(&bytes,maxLength:bytes.count);if count<=0 {break};Self.body.append(contentsOf:bytes.prefix(count))}
        }
        client?.urlProtocol(self,didReceive:HTTPURLResponse(url:request.url!,statusCode:503,httpVersion:nil,headerFields:["Content-Type":"application/json"])!,cacheStoragePolicy:.notAllowed)
        client?.urlProtocol(self,didLoad:Data("{}".utf8));client?.urlProtocolDidFinishLoading(self)
    }
    override func stopLoading() {}
}
private final class RequiredNullBuilder<T:Decodable>:AlamofireDecodableRequestBuilder<T> {
    override func createAlamofireSession(interceptor:RequestInterceptor? = nil)->Alamofire.Session {
        let config=URLSessionConfiguration.ephemeral;config.protocolClasses=[RequiredNullProtocol.self]
        return Alamofire.Session(configuration:config,interceptor:interceptor)
    }
}
private struct RequiredNullFactory:RequestBuilderFactory {
    func getNonDecodableBuilder<T>()->RequestBuilder<T>.Type {AlamofireRequestBuilder<T>.self}
    func getBuilder<T:Decodable>()->RequestBuilder<T>.Type {RequiredNullBuilder<T>.self}
}
