    private func values() throws -> [String:Any] {try JSONSerialization.jsonObject(with:Data(fixtures.utf8)) as! [String:Any]}
    func testDirectRequiredNullZeroTimedAndOptionalStates() throws {
        let cases=try values()["cases"] as! [[String:Any]];XCTAssertEqual(cases.count,20)
        for fixture in cases {
            for key in ["target","actual"] {
                let original=fixture[key] as! [String:Any],data=try JSONSerialization.data(withJSONObject:original)
                let encoded:Data
                if key=="target" {encoded=try CodableHelper.jsonEncoder.encode(CodableHelper.jsonDecoder.decode(ExecutionTargetValues.self,from:data))}
                else {encoded=try CodableHelper.jsonEncoder.encode(CodableHelper.jsonDecoder.decode(WorkoutSetValues.self,from:data))}
                XCTAssertEqual(try JSONSerialization.jsonObject(with:encoded) as! NSDictionary,original as NSDictionary,fixture["label"] as! String+" "+key)
            }
        }
    }
    private func checkHTTP(_ kind:String,_ original:[String:Any]) throws {
        let base=FitAppClientSwiftAPI.basePath,factory=FitAppClientSwiftAPI.requestBuilderFactory
        defer {FitAppClientSwiftAPI.basePath=base;FitAppClientSwiftAPI.requestBuilderFactory=factory}
        FitAppClientSwiftAPI.basePath="http://wwc-required-null.invalid/api/v1";FitAppClientSwiftAPI.requestBuilderFactory=RequiredNullFactory()
        let data=try JSONSerialization.data(withJSONObject:original)
        if kind=="record" {
            let payload=try CodableHelper.jsonDecoder.decode(ExecutionSetRecordPayload.self,from:data)
            let builder=WorkoutExecutionAPI.recordStudentSetExecutionWithRequestBuilder(sessionId:"session",idempotencyKey:"operation-id",executionSetRecordPayload:payload,acceptLanguage:"pt-BR",ifMatch:"set-revision")
            try checkAttempts(builder,kind,original)
        } else {
            let payload=try CodableHelper.jsonDecoder.decode(ExecutionSetAmendPayload.self,from:data)
            let builder=WorkoutExecutionAPI.amendStudentSetExecutionWithRequestBuilder(sessionId:"session",setExecutionId:"set-execution",idempotencyKey:"operation-id",ifMatch:"set-revision",executionSetAmendPayload:payload,acceptLanguage:"pt-BR")
            try checkAttempts(builder,kind,original)
        }
    }
    private func checkAttempts<T>(_ builder:RequestBuilder<T>,_ kind:String,_ original:[String:Any]) throws {
        // Retry the immutable prepared request. Rebuilding a new intention is
        // separate from replaying the same request bytes and preconditions.
        var firstBody:Data?
        for _ in 0..<2 {
        RequiredNullProtocol.captured=nil;RequiredNullProtocol.body=Data()
        let done=expectation(description:"required null HTTP "+kind)
        builder.execute(.global()) {result in
            if case .success = result {XCTFail("Synthetic 503 must not confirm success")}
            done.fulfill()
        }
        wait(for:[done],timeout:10)
        let request=try XCTUnwrap(RequiredNullProtocol.captured)
        XCTAssertEqual(request.httpMethod,"POST")
        XCTAssertEqual(request.url?.path,"/api/v1/student/workout-sessions/session/set-executions"+(kind=="record" ? "" : "/set-execution/amendments"))
        XCTAssertEqual(request.value(forHTTPHeaderField:"Idempotency-Key"),"operation-id")
        XCTAssertEqual(request.value(forHTTPHeaderField:"If-Match"),"set-revision")
        XCTAssertEqual(request.value(forHTTPHeaderField:"Accept-Language"),"pt-BR")
        XCTAssertEqual(try JSONSerialization.jsonObject(with:RequiredNullProtocol.body) as! NSDictionary,original as NSDictionary)
        if let first=firstBody {XCTAssertEqual(RequiredNullProtocol.body,first)} else {firstBody=RequiredNullProtocol.body}
        }
    }
    func testRealRecordAndAmendHTTPRequiredNullAndOptionalStates() throws {
        let cases=try values()["cases"] as! [[String:Any]];XCTAssertEqual(cases.count,20)
        for fixture in cases {for kind in ["record","amend"] {try checkHTTP(kind,fixture[kind] as! [String:Any])}}
    }
    func testRealSkippedHTTPKeepsActualAndReplacementAbsent() throws {
        let all=try values();try checkHTTP("record",all["skippedRecord"] as! [String:Any]);try checkHTTP("amend",all["skippedAmend"] as! [String:Any])
    }
